    code: usize,
    comments: usize,
    blobs: HashMap<String, CodeStats>,
}

impl CodeStats {
    fn new() -> Self {
        Self { blanks: 0, code: 0, comments: 0, blobs: HashMap::new() }
    }
    fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }
}

