  -s, --sort <sort>                    Sort languages based on column [possible values: files,
                                       lines, blanks, code, comments]
  -r, --rsort <rsort>                  Reverse sort languages based on column [possible values:
                                       files, lines, blanks, code, comments]
  -t, --types <types>                  Filters output by language type, separated by a comma. i.e.
                                       -t=Rust,Markdown
  -C, --compact                        Do not print statistics about embedded languages.
  -n, --num-format <num_format_style>  Format of printed numbers, i.e., plain (1234, default),
                                       commas (1,234), dots (1.234), or underscores (1_234). Cannot
                                       be used with --output. [possible values: commas, dots, plain,
                                       underscores]
  -v, --verbose...                     Set log output level:
                                                               1: to show unknown file extensions,
                                                               2: reserved for future debugging,
                                                               3: enable file level trace. Not
                                                               recommended on multiple files
  -h, --help                           Print help
  -V, --version                        Print version
"#;
    print!("{}", help);
}

fn print_version() {
    println!("tokei 14.0.0 compiled with serialization support: json");
}

#[derive(Debug, Clone)]
struct FileReport {
    name: String,
    stats: CodeStats,
}

#[derive(Debug, Clone)]
struct BlobReport {
    stats: CodeStats,
    name: String,
}

fn collect_files_recursive(dir: &Path, out: &mut Vec<PathBuf>, hidden: bool, exclude_patterns: &[String], no_ignore_dot: bool, no_ignore_vcs: bool, no_ignore_parent: bool, verbose: u8) {
    // Use walkdir for simplicity, handling hidden and exclude.
    // For ignore files, we will implement simple handling for .ignore and .tokeignore if not disabled, and .gitignore if not disabled and .git folder exists.
    // We'll also handle parent ignore if not disabled.

    // Build globset for exclude
    use globset::{Glob, GlobSetBuilder};
    let mut builder = GlobSetBuilder::new();
    for pat in exclude_patterns {
        // gitignore semantics: we will treat pattern as glob matching file name or path.
        // For simplicity, try to create glob, if fails ignore.
        if let Ok(g) = Glob::new(pat) {
            builder.add(g);
        } else {
            // try with **/ pattern?
            if let Ok(g) = Glob::new(&format!("**/{}", pat)) {
                builder.add(g);
            }
        }
    }
    let exclude_set = builder.build().ok();

    // For ignore files handling, we need to collect patterns from .ignore, .tokeignore, .gitignore along the walk.
    // For simplicity, we will walk and for each directory, check for ignore files and build sets.

    // We'll use walkdir with filtering.
    let walker = walkdir::WalkDir::new(dir).follow_links(false).into_iter();

    // We'll maintain a stack of ignore sets per directory?
    // For simplicity, for each file, we check if any ignore file in its ancestors contains pattern matching file name, if so skip.

    // To implement, we could for each file, walk up from file's parent to dir root (and possibly beyond for parent ignore), reading ignore files.

    // But for MVP, we ignore ignore files handling and only handle hidden and exclude, which matches many cases where no .git present.

    for entry in walker.filter_entry(|e| {
        // Check hidden
        if !hidden {
            if let Some(file_name) = e.file_name().to_str() {
                if file_name.starts_with('.') {
                    // Allow . if it's "." or ".."? walkdir should handle.
                    // Skip hidden files/dirs
                    // But need to allow ./. ?
                    // If it's a directory starting with ., skip descending?
                    return false;
                }
            }
            // Also check any component starting with .?
            // For path like /tmp/.../.hidden/file, the hidden dir component would be caught when that dir is encountered as entry, so its children won't be visited if we return false for dir.
        }
        // Check exclude for directory? Use file name matching
        if let Some(ref set) = exclude_set {
            let path = e.path();
            // Check if any pattern matches path or file name
            // We will match against file name and also full path
            let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            // Globset matching: try path
            // For simplicity, check if set matches file_name or path string
            if set.is_match(file_name) {
                return false;
            }
            // Also try relative path string?
            // Convert path to string and check
            let path_str = path.to_string_lossy();
            if set.is_match(path_str.as_ref()) {
                return false;
            }
        }
        true
    }) {
        match entry {
            Ok(e) => {
                let path = e.path();
                if path.is_file() {
                    // Check hidden for file itself (if hidden flag false, file starting with . should have been filtered via filter_entry? But file_name check for file entry also filtered)
                    // Additional check for hidden components in path
                    if !hidden {
                        let mut is_hidden = false;
                        for comp in path.components() {
                            if let Some(comp_str) = comp.as_os_str().to_str() {
                                if comp_str.starts_with('.') && comp_str != "." && comp_str != ".." {
                                    // Check if this component is not the root input dir itself? For input dir "." not hidden.
                                    // If any component hidden, skip
                                    // But we need to allow if comp is file name itself starting with . -> already filtered, but for parent hidden dirs also.
                                    is_hidden = true;
                                    break;
                                }
                            }
                        }
                        if is_hidden {
                            continue;
                        }
                    }

                    // Exclude already handled via filter_entry for file, but also for file name matching: we already filtered, but double-check
                    if let Some(ref set) = exclude_set {
                        let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                        if set.is_match(file_name) {
                            continue;
                        }
                        let path_str = path.to_string_lossy();
                        if set.is_match(path_str.as_ref()) {
                            continue;
                        }
                    }

                    // For ignore files: check .ignore, .tokeignore, .gitignore in ancestors
                    if !no_ignore_dot || !no_ignore_vcs || !no_ignore_parent {
                        // We'll implement simple check: walk up from file's parent to root filesystem, collecting ignore patterns.
                        // For each directory, if it contains .tokeignore or .ignore or .gitignore, read patterns and check if file matches.
                        // This is expensive but okay for small.

                        let mut current = path.parent();
                        let mut is_ignored = false;
                        while let Some(dir) = current {
                            // Stop if we go beyond the initial walk root and no_ignore_parent true?
                            // If no_ignore_parent, only check the file's immediate parent? Actually spec: don't respect ignore files in parent directories. So for no_ignore_parent, we should only check the file's own directory, not ancestors.
                            // For simplicity, if no_ignore_parent true, only check first iteration (file's parent), then break.

                            // Determine if this dir is parent of input walk root? We need to know input root. For now, we pass dir as initial root, and we walk recursively, so current will be within root. For parent ignore, we also need to check parents beyond root up to filesystem root? In tokei, it respects parent ignore files beyond the counted directory (like if you count child dir, parent .gitignore may affect). So we should check beyond.

                            // For our simple implementation, we will check all ancestors up to filesystem root unless no_ignore_parent disables beyond first.

                            // Check .tokeignore and .ignore if not no_ignore_dot
                            if !no_ignore_dot {
                                for ig_file in &[".tokeignore", ".ignore"] {
                                    let ig_path = dir.join(ig_file);
                                    if ig_path.is_file() {
                                        if let Ok(content) = fs::read_to_string(&ig_path) {
                                            for pat_line in content.lines() {
                                                let pat = pat_line.trim();
                                                if pat.is_empty() || pat.starts_with('#') { continue; }
                                                // glob match
                                                if let Ok(glob) = globset::Glob::new(pat) {
                                                    let set = globset::GlobSetBuilder::new().add(glob).build().ok();
                                                    if let Some(s) = set {
                                                        let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                                                        if s.is_match(file_name) || s.is_match(path.to_string_lossy().as_ref()) {
                                                            is_ignored = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                            }
                                            if is_ignored { break; }
                                        }
                                    }
                                }
                                if is_ignored { break; }
                            }

                            // Check .gitignore if not no_ignore_vcs
                            if !no_ignore_vcs {
                                let gitignore_path = dir.join(".gitignore");
                                // Only respect if .git folder exists in same dir or parent? According to earlier test, .gitignore only respected if .git folder exists.
                                // Check if .git exists in this dir or any parent? Actually we saw .gitignore in dir without .git folder was not respected. So need .git folder existence.
                                // Check if dir contains .git or any ancestor contains .git?
                                let mut has_git = false;
                                let mut check_git = Some(dir);
                                while let Some(gdir) = check_git {
                                    if gdir.join(".git").is_dir() {
                                        has_git = true;
                                        break;
                                    }
                                    check_git = gdir.parent();
                                }
                                if has_git && gitignore_path.is_file() {
                                    if let Ok(content) = fs::read_to_string(&gitignore_path) {
                                        for pat_line in content.lines() {
                                            let pat = pat_line.trim();
                                            if pat.is_empty() || pat.starts_with('#') { continue; }
                                            if let Ok(glob) = globset::Glob::new(pat) {
                                                let set = globset::GlobSetBuilder::new().add(glob).build().ok();
                                                if let Some(s) = set {
                                                    let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                                                    if s.is_match(file_name) || s.is_match(path.to_string_lossy().as_ref()) {
                                                        is_ignored = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        if is_ignored { break; }
                                    }
                                }
                            }

                            if no_ignore_parent {
                                break;
                            }
                            current = dir.parent();
                        }
                        if is_ignored {
                            continue;
                        }
                    }

                    out.push(path.to_path_buf());
                }
            },
            Err(_) => continue,
        }
    }
}

fn detect_language(path: &Path, ext_map: &HashMap<String, String>, filename_map: &HashMap<String, String>) -> Option<String> {
    // Check filename exact
    if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
        let lower = fname.to_lowercase();
        if let Some(lang) = filename_map.get(&lower) {
            return Some(lang.clone());
        }
        if let Some(lang) = filename_map.get(fname) {
            return Some(lang.clone());
        }
        // Also check full filename as stored (like CMakeLists.txt)
        if let Some(lang) = ext_map.get(&lower) {
            // This may be filename as well
            return Some(lang.clone());
        }
    }
    // Check extension
    if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
        let lower = ext.to_lowercase();
        if let Some(lang) = ext_map.get(&lower) {
            return Some(lang.clone());
        }
    }
    // Check shebang
    if let Ok(content) = fs::read_to_string(path) {
        if let Some(first_line) = content.lines().next() {
            if first_line.starts_with("#!") {
                let lower = first_line.to_lowercase();
                // Simple detection
                if lower.contains("python") { return Some("Python".to_string()); }
                if lower.contains("bash") { return Some("BASH".to_string()); }
                if lower.contains("sh") { return Some("Shell".to_string()); }
                if lower.contains("ruby") { return Some("Ruby".to_string()); }
                if lower.contains("perl") { return Some("Perl".to_string()); }
                if lower.contains("node") { return Some("JavaScript".to_string()); }
                if lower.contains("php") { return Some("PHP".to_string()); }
            }
        }
    }
    // Fallback to plain text for .txt
    if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
        let low = ext.to_lowercase();
        if low=="txt" || low=="text" {
            return Some("Plain Text".to_string());
        }
    }
    None
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print_help();
        return;
    }
    if args.iter().any(|a| a=="-V" || a=="--version") {
        print_version();
        return;
    }

    let cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("columns").short('c').long("columns").value_name("columns").help("Sets a strict column width of the output, only available for terminal output."))
        .arg(Arg::new("exclude").short('e').long("exclude").value_name("exclude").help("Ignore all files & directories matching the pattern.").action(ArgAction::Append))
        .arg(Arg::new("files").short('f').long("files").help("Will print out statistics on individual files.").action(ArgAction::SetTrue))
        .arg(Arg::new("input").short('i').long("input").value_name("file_input").help("Gives statistics from a previous tokei run. Can be given a file path, or \"stdin\" to read from stdin."))
        .arg(Arg::new("hidden").long("hidden").help("Count hidden files.").action(ArgAction::SetTrue))
        .arg(Arg::new("languages").short('l').long("languages").help("Prints out supported languages and their extensions.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore").long("no-ignore").help("Don't respect ignore files (.gitignore, .ignore, etc.). This implies --no-ignore-parent, --no-ignore-dot, and --no-ignore-vcs.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-parent").long("no-ignore-parent").help("Don't respect ignore files (.gitignore, .ignore, etc.) in parent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-dot").long("no-ignore-dot").help("Don't respect .ignore and .tokeignore files, including those in parent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-vcs").long("no-ignore-vcs").help("Don't respect VCS ignore files (.gitignore, .hgignore, etc.) including those in parent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").value_name("output").help("Outputs Tokei in a specific format. Compile with additional features for more format support."))
        .arg(Arg::new("streaming").long("streaming").value_name("streaming").help("prints the (language, path, lines, blanks, code, comments) records as simple lines or as Json for batch processing").value_parser(["simple","json"]))
        .arg(Arg::new("sort").short('s').long("sort").value_name("sort").help("Sort languages based on column").value_parser(["files","lines","blanks","code","comments"]))
        .arg(Arg::new("rsort").short('r').long("rsort").value_name("rsort").help("Reverse sort languages based on column").value_parser(["files","lines","blanks","code","comments"]))
        .arg(Arg::new("types").short('t').long("types").value_name("types").help("Filters output by language type, separated by a comma. i.e. -t=Rust,Markdown"))
        .arg(Arg::new("compact").short('C').long("compact").help("Do not print statistics about embedded languages.").action(ArgAction::SetTrue))
        .arg(Arg::new("num-format").short('n').long("num-format").value_name("num_format_style").help("Format of printed numbers, i.e., plain (1234, default), commas (1,234), dots (1.234), or underscores (1_234). Cannot be used with --output.").value_parser(["commas","dots","plain","underscores"]).conflicts_with("output"))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Set log output level").action(ArgAction::Count))
        .arg(Arg::new("input_paths").value_name("input").num_args(0..).help("The path(s) to the file or directory to be counted. (default current directory)"))
        .arg(Arg::new("help").short('h').long("help").help("Print help").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::SetTrue))
        ;

    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => { e.exit() }
    };

    if matches.get_flag("help") { print_help(); return; }
    if matches.get_flag("version") { print_version(); return; }

    if let Some(out) = matches.get_one::<String>("output") {
        match out.as_str() {
            "json" => {},
            "yaml" => {
                eprintln!("error: invalid value 'yaml' for '--output <output>': This version of tokei was compiled without any 'yaml' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features yaml\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\nFor more information, try '--help'.");
                process::exit(2);
            },
            "cbor" => {
                eprintln!("error: invalid value 'cbor' for '--output <output>': This version of tokei was compiled without any 'cbor' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features cbor\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\nFor more information, try '--help'.");
                process::exit(2);
            },
            _ => {
                eprintln!("error: invalid value '{}' for '--output <output>': \"{}\" is not a supported serialization format\n\nFor more information, try '--help'.", out, out);
                process::exit(2);
            }
        }
    }

    if let Some(col_str) = matches.get_one::<String>("columns") {
        if col_str.parse::<usize>().is_err() {
            eprintln!("error: invalid value '{}' for '--columns <columns>': invalid digit found in string\n\nFor more information, try '--help'.", col_str);
            process::exit(2);
        }
    }

    if matches.get_flag("languages") {
        let table = include_str!("../languages_table.txt");
        print!("{}", table);
        return;
    }

    let files_flag = matches.get_flag("files");
    let hidden_flag = matches.get_flag("hidden");
    let compact_flag = matches.get_flag("compact");
    let no_ignore = matches.get_flag("no-ignore");
    let no_ignore_parent = matches.get_flag("no-ignore-parent") || no_ignore;
    let no_ignore_dot = matches.get_flag("no-ignore-dot") || no_ignore;
    let no_ignore_vcs = matches.get_flag("no-ignore-vcs") || no_ignore;
    let columns = matches.get_one::<String>("columns").and_then(|s| s.parse::<usize>().ok());
    let sort = matches.get_one::<String>("sort").map(|s| s.as_str());
    let rsort = matches.get_one::<String>("rsort").map(|s| s.as_str());
    let types_filter = matches.get_one::<String>("types").map(|s| s.as_str());
    let num_format = matches.get_one::<String>("num-format").map(|s| s.as_str()).unwrap_or("plain");
    let streaming = matches.get_one::<String>("streaming").map(|s| s.as_str());
    let input_file = matches.get_one::<String>("input").map(|s| s.as_str());
    let verbose = matches.get_count("verbose");

    let exclude_patterns: Vec<String> = matches.get_many::<String>("exclude").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let input_paths: Vec<String> = matches.get_many::<String>("input_paths").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();

    // Collect files
    let languages = get_languages();
    let ext_map = build_extension_map(&languages);
    let mut filename_map: HashMap<String, String> = HashMap::new();
    for lang in &languages {
        for fname in &lang.filenames {
            filename_map.insert(fname.to_lowercase(), lang.name.to_string());
        }
    }
    // Add extra file mappings from ext_map (filenames)
    for (k,v) in &ext_map {
        if !k.contains('.') {
            // could be filename like makefile, dockerfile
            if k=="makefile" || k=="dockerfile" || k=="cmakelists.txt" || k=="bash" || k=="sh" {
                filename_map.insert(k.clone(), v.clone());
            }
        }
    }

    let paths_to_walk: Vec<PathBuf> = if input_paths.is_empty() { vec![PathBuf::from(".")] } else { input_paths.iter().map(|p| PathBuf::from(p)).collect() };

    let mut all_files: Vec<PathBuf> = Vec::new();
    for p in &paths_to_walk {
        if p.is_file() {
            all_files.push(p.clone());
        } else if p.is_dir() {
            collect_files_recursive(p, &mut all_files, hidden_flag, &exclude_patterns, no_ignore_dot, no_ignore_vcs, no_ignore_parent, verbose);
        } else {
            if verbose>0 {
                eprintln!("[WARN  tokei::files] File not found: {:?}", p);
            }
        }
    }

    all_files.sort();
    all_files.dedup();

    let types_set: Option<HashSet<String>> = if let Some(t) = types_filter {
        let set: HashSet<String> = t.split(',').map(|s| s.trim().to_string()).collect();
        Some(set)
    } else { None };

    // Structures for aggregation
    // lang -> (files count, main stats, reports, children)
    let mut lang_totals: HashMap<String, (usize, CodeStats, Vec<FileReport>, HashMap<String, Vec<BlobReport>>)> = HashMap::new();

    let mut total_files = 0usize;
    let mut total_blanks = 0usize;
    let mut total_code = 0usize;
    let mut total_comments = 0usize;
    let mut per_language_reports_for_total: HashMap<String, Vec<FileReport>> = HashMap::new();

    let mut streaming_simple_rows: Vec<(String, String, usize, usize, usize, usize)> = Vec::new();
    let mut streaming_json_rows: Vec<serde_json::Value> = Vec::new();

    for file_path in &all_files {
        let lang_name_opt = detect_language(file_path, &ext_map, &filename_map);
        let lang_name = match lang_name_opt {
            Some(n) => n,
            None => {
                if verbose>=1 {
                    if let Some(ext) = file_path.extension().and_then(|e| e.to_str()) {
                        eprintln!("[WARN  tokei::language::language_type] Unknown extension: {}", ext);
                    }
                }
                continue;
            }
        };

        if let Some(ref set) = types_set {
            if !set.contains(&lang_name) {
                continue;
            }
        }

        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(_) => {
                match fs::read(file_path) {
                    Ok(bytes) => String::from_utf8_lossy(&bytes).to_string(),
                    Err(_) => continue,
                }
            }
        };

        let lang_def_opt = languages.iter().find(|l| l.name == lang_name);
        let stats = if let Some(lang_def) = lang_def_opt {
            count_file(file_path, lang_def, &content, &languages, &ext_map)
        } else {
            // Fallback: treat as plain text? Actually for unknown but detected via ext_map we have lang_def, but for safety fallback to code counting
            let mut s = CodeStats::new();
            for line in content.lines() {
                if line.trim().is_empty() { s.blanks+=1; } else { s.code+=1; }
            }
            s
        };

        if streaming.is_some() {
            streaming_simple_rows.push((lang_name.clone(), file_path.to_string_lossy().to_string(), stats.lines(), stats.code, stats.comments, stats.blanks));
            let mut blobs_map = serde_json::Map::new();
            for (b_lang, b_stats) in &stats.blobs {
                blobs_map.insert(b_lang.clone(), serde_json::json!({
                    "blanks": b_stats.blanks,
                    "code": b_stats.code,
                    "comments": b_stats.comments,
                    "blobs": {}
                }));
            }
            let json_val = serde_json::json!({
                "language": lang_name,
                "stats": {
                    "name": file_path.to_string_lossy(),
                    "stats": {
                        "blanks": stats.blanks,
                        "blobs": blobs_map,
                        "code": stats.code,
                        "comments": stats.comments
                    }
                }
            });
            streaming_json_rows.push(json_val);
        }

        total_files+=1;
        let (all_blanks, all_code, all_comments) = sum_recursively(&stats);
        total_blanks+=all_blanks;
        total_code+=all_code;
        total_comments+=all_comments;

        let entry = lang_totals.entry(lang_name.clone()).or_insert((0, CodeStats::new(), Vec::new(), HashMap::new()));
        entry.0 +=1;
        entry.1.blanks += stats.blanks;
        entry.1.code += stats.code;
        entry.1.comments += stats.comments;

        for (blob_lang, blob_stats) in &stats.blobs {
            let child_entry = entry.3.entry(blob_lang.clone()).or_insert(Vec::new());
            child_entry.push(BlobReport { stats: blob_stats.clone(), name: file_path.to_string_lossy().to_string() });
        }

        let report = FileReport { name: file_path.to_string_lossy().to_string(), stats: stats.clone() };
        entry.2.push(report.clone());
        per_language_reports_for_total.entry(lang_name.clone()).or_insert(Vec::new()).push(report);
    }

    // Handle input merging (simple)
    // For this MVP we ignore previous data for table, but for json we could merge
    // We'll attempt to merge if input_file provided and output is json
