use clap::{Command, Arg, ArgAction};
use std::collections::{HashMap, HashSet};
use std::process;
use std::path::{Path, PathBuf};
use std::fs;
use std::io::{self, Read};

mod languages;
mod count;

use languages::{get_languages, build_extension_map};
use count::{ count_file, CodeStats, sum_recursively };

