                    let mut footer = format!(" {:<width$}", report.name, width=lang_width-1);
                    let main_lines = report.stats.blanks + report.stats.code + report.stats.comments;
                    footer.push_str(&format!("{:>13}{:>13}{:>13}{:>13}{:>13}",
                        "",
