                        format_number(report.stats.code),
                        format_number(report.stats.comments),
                        format_number(report.stats.blanks)
                    ));
                    println!("{}", footer);
                } else {
                    let mut file_row = format!(" {:<width$}", report.name, width=lang_width-1);
                    let lines = report.stats.blanks + report.stats.code + report.stats.comments;
                    file_row.push_str(&format!("{:>13}{:>13}{:>13}{:>13}{:>13}",
