use std::collections::HashMap;
use std::path::Path;
use crate::languages::Language;

#[derive(Debug, Clone)]
pub struct CodeStats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub blobs: HashMap<String, CodeStats>,
}

impl CodeStats {
    pub fn new() -> Self {
        Self { blanks: 0, code: 0, comments: 0, blobs: HashMap::new() }
    }
    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }
}

pub fn sum_recursively(stats: &CodeStats) -> (usize, usize, usize) {
    let mut blanks = stats.blanks;
    let mut code = stats.code;
    let mut comments = stats.comments;
    for (_lang, blob) in &stats.blobs {
        let (b_blanks, b_code, b_comments) = sum_recursively(blob);
        blanks += b_blanks;
        code += b_code;
        comments += b_comments;
    }
    (blanks, code, comments)
}

fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

pub fn count_file(path: &Path, lang: &Language, content: &str, all_langs: &[Language], ext_map: &HashMap<String, String>) -> CodeStats {
    if lang.is_markdown {
        return count_markdown(content, all_langs, ext_map);
    }
    if lang.name == "Plain Text" {
        let mut stats = CodeStats::new();
        for line in content.lines() {
            if is_blank(line) { stats.blanks+=1; } else { stats.comments+=1; }
        }
        return stats;
    }
    if lang.name == "JSON" {
        let mut stats = CodeStats::new();
        for line in content.lines() {
            if is_blank(line) { stats.blanks+=1; } else { stats.code+=1; }
        }
        return stats;
    }
    // Generic parser
    let mut stats = CodeStats::new();
    let mut block_stack: Vec<(&str, &str)> = Vec::new();
    let mut in_string: Option<String> = None;
    let mut string_is_triple = false;

    let mut line_comments = lang.line_comments.clone();
    line_comments.sort_by(|a,b| b.len().cmp(&a.len()));
    let mut block_comments = lang.block_comments.clone();
    block_comments.sort_by(|a,b| b.0.len().cmp(&a.0.len()));
    let mut quotes = lang.quotes.clone();
    quotes.sort_by(|a,b| b.0.len().cmp(&a.0.len()));

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if !block_stack.is_empty() {
                stats.comments+=1;
            } else if in_string.is_some() {
                stats.code+=1;
            } else {
                stats.blanks+=1;
            }
            continue;
        }

        let mut has_code = false;
        let mut has_comment = false;
        let mut pos = 0usize;
        let line_len = line.len();
        if !block_stack.is_empty() { has_comment = true; }
        if in_string.is_some() { has_code = true; }

        while pos < line_len {
            let remaining = &line[pos..];
            if let Some(ref delim) = in_string.clone() {
                if remaining.starts_with(delim) {
                    let mut escaped = false;
                    if !string_is_triple {
                        let mut cnt = 0;
                        let mut idx = pos;
                        while idx>0 {
                            idx-=1;
                            if line.as_bytes()[idx]==b'\\' { cnt+=1; } else { break; }
                        }
                        if cnt%2==1 { escaped=true; }
                    }
                    if !escaped {
                        in_string=None;
                        string_is_triple=false;
                        pos+=delim.len();
                        continue;
                    }
                }
                if let Some(ch) = remaining.chars().next() {
                    if !ch.is_whitespace() { has_code=true; }
                    pos+=ch.len_utf8();
                } else { break; }
                continue;
            }
            if !block_stack.is_empty() {
                let (_, end_delim) = block_stack.last().unwrap().clone();
                if remaining.starts_with(end_delim) {
                    block_stack.pop();
                    pos+=end_delim.len();
                    continue;
                }
                if lang.nested {
                    let mut found=false;
                    for (s,e) in &block_comments {
                        if remaining.starts_with(*s) {
                            block_stack.push((*s,*e));
                            pos+=s.len();
                            found=true;
                            break;
                        }
                    }
                    if found { has_comment=true; continue; }
                }
                has_comment=true;
                if let Some(ch) = remaining.chars().next() { pos+=ch.len_utf8(); } else { break; }
                continue;
            }
            // line comment
            let mut is_line_comment=false;
            for lc in &line_comments {
                if remaining.starts_with(*lc) {
                    if !has_code { has_comment=true; }
                    is_line_comment=true;
                    break;
                }
            }
            if is_line_comment { break; }
            // block comment start
            let mut found_block=false;
            for (s,e) in &block_comments {
                if remaining.starts_with(*s) {
                    block_stack.push((*s,*e));
                    has_comment=true;
                    pos+=s.len();
                    found_block=true;
                    break;
                }
            }
            if found_block { continue; }
