            if let Some(ch) = remaining.chars().next() {
                if !ch.is_whitespace() { has_code=true; }
                pos+=ch.len_utf8();
            } else { break; }
        }

        if has_code { stats.code+=1; }
        else if has_comment { stats.comments+=1; }
        else { stats.code+=1; }
    }
    stats
}

